      "  account_id TEXT NOT NULL PRIMARY KEY CHECK (typeof(account_id) = 'text' AND length(account_id) = 41 AND substr(account_id, 1, 9) = 'mtl-acct-' AND substr(account_id, 10) NOT GLOB '*[^a-p]*'),",
