      "  net_minor INTEGER NOT NULL CHECK (typeof(net_minor) = 'integer' AND net_minor BETWEEN -10000000000 AND 10000000000),",
      "  net_complete INTEGER NOT NULL CHECK (typeof(net_complete) = 'integer' AND net_complete IN (0, 1)),",
      "  program TEXT NULL CHECK (program IS NULL OR (typeof(program) = 'text' AND length(program) BETWEEN 1 AND 60 AND program = trim(program) AND program NOT GLOB '[=+@-]*' AND program NOT GLOB '*[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]*')),",
      "  premium_text TEXT NULL CHECK (premium_text IS NULL OR (typeof(premium_text) = 'text' AND length(premium_text) BETWEEN 1 AND 60 AND premium_text = trim(premium_text) AND premium_text NOT GLOB '[=+@-]*' AND premium_text NOT GLOB '*[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]*')),",
      "  premium_basis TEXT NULL CHECK (premium_basis IS NULL OR (premium_basis IN ('troy_ounce', 'unit'))),",
      "  inspection TEXT NULL CHECK (inspection IS NULL OR (inspection IN ('passed', 'failed', 'pending'))),",
      "  events_json TEXT NOT NULL CHECK (typeof(events_json) = 'text' AND length(events_json) BETWEEN 2 AND 100000 AND json_valid(events_json) AND events_json NOT GLOB '*[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]*'),",
      "  CHECK ((stated_mass_value IS NULL) = (stated_mass_unit IS NULL)),",
      "  CHECK ((purity_text IS NULL) = (purity_value IS NULL)),",
      "  CHECK ((fine_troy_oz IS NULL) = (fine_basis IS NULL)),",
      "  CHECK ((content_hold IS NULL) = (content_missing IS NULL)),",
      "  CHECK ((fine_troy_oz IS NULL) <> (content_hold IS NULL)),",
      "  CHECK ((metal_uncertain_guard IS NULL) = (metal_uncertain_evidence IS NULL)),",
      "  CHECK (metal_uncertain_guard IS NOT NULL OR metal_uncertain_metal IS NULL),",
