      "  record_key TEXT NULL CHECK (record_key IS NULL OR (typeof(record_key) = 'text' AND substr(record_key, -64) NOT GLOB '*[^a-p]*' AND ((length(record_key) = 77 AND substr(record_key, 1, 13) = 'costco-order-') OR (length(record_key) = 79 AND substr(record_key, 1, 15) = 'costco-receipt-') OR (length(record_key) = 78 AND substr(record_key, 1, 14) = 'walmart-order-') OR (length(record_key) = 81 AND substr(record_key, 1, 17) = 'collectpure-sell-')) AND substr(record_key, 1, length(source) + 1) = source || '-')),",
      "  channel TEXT NOT NULL CHECK (channel IN ('online', 'warehouse')),",
