      "  date_to TEXT NOT NULL CHECK (typeof(date_to) = 'text' AND length(date_to) = 10 AND date(date_to) IS date_to AND date_to >= date_from),",
      "  stated INTEGER NULL CHECK (stated IS NULL OR (typeof(stated) = 'integer' AND stated BETWEEN 0 AND 1000000)),",
